  valid = signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
}
const head = body.workflow_run?.head_branch ?? body.workflow_run?.head_commit?.message ?? body.workflow_run?.head_sha ?? '';
const jiraKey = String(head).match(/\b[A-Z][A-Z0-9]+-\d+\b/)?.[0] ?? null;
const runUrl = body.workflow_run?.html_url ?? null;
return [{ json: { valid, jiraKey, runUrl, conclusion: body.workflow_run?.conclusion ?? null, commitSha: body.workflow_run?.head_sha ?? null, runId: body.workflow_run?.id ?? null, ai_calls: 0 } }];
